diff --git a/MagickCore/draw.c b/MagickCore/draw.c
index 26c38596813..36ca03fdc96 100644
--- a/MagickCore/draw.c
+++ b/MagickCore/draw.c
@@ -2300,23 +2300,19 @@ static MagickBooleanType CheckPrimitiveExtent(MVGInfo *mvg_info,
   */
   extent=(double) mvg_info->offset+pad+PrimitiveExtentPad+1;
   quantum=sizeof(**mvg_info->primitive_info);
-  if (((extent*quantum) < (double) SSIZE_MAX) &&
-      ((extent*quantum) < (double) GetMaxMemoryRequest()))
+  if (extent <= (double) *mvg_info->extent)
+    return(MagickTrue);
+  *mvg_info->primitive_info=(PrimitiveInfo *) ResizeQuantumMemory(
+    *mvg_info->primitive_info,(size_t) extent,quantum);
+  if (*mvg_info->primitive_info != (PrimitiveInfo *) NULL)
     {
-      if (extent <= (double) *mvg_info->extent)
-        return(MagickTrue);
-      *mvg_info->primitive_info=(PrimitiveInfo *) ResizeQuantumMemory(
-        *mvg_info->primitive_info,(size_t) extent,quantum);
-      if (*mvg_info->primitive_info != (PrimitiveInfo *) NULL)
-        {
-          register ssize_t
-            i;
+      register ssize_t
+        i;

-          *mvg_info->extent=(size_t) extent;
-          for (i=mvg_info->offset+1; i < (ssize_t) extent; i++)
-            (*mvg_info->primitive_info)[i].primitive=UndefinedPrimitive;
-          return(MagickTrue);
-        }
+      *mvg_info->extent=(size_t) extent;
+      for (i=mvg_info->offset+1; i < (ssize_t) extent; i++)
+        (*mvg_info->primitive_info)[i].primitive=UndefinedPrimitive;
+      return(MagickTrue);
     }
   /*
     Reallocation failed, allocate a primitive to facilitate unwinding.
diff --git a/MagickCore/memory.c b/MagickCore/memory.c
index 73593c2fa43..52b1779a700 100644
--- a/MagickCore/memory.c
+++ b/MagickCore/memory.c
@@ -638,6 +638,8 @@ MagickExport void *AcquireQuantumMemory(const size_t count,const size_t quantum)

   if (HeapOverflowSanityCheckGetSize(count,quantum,&size) != MagickFalse)
     return((void *) NULL);
+  if (size > GetMaxMemoryRequest())
+    return(NULL);
   return(AcquireMagickMemory(size));
 }

@@ -1010,6 +1012,7 @@ MagickExport size_t GetMaxMemoryRequest(void)
       char
         *value;

+      max_memory_request=(size_t) MagickULLConstant(~0);
       value=GetPolicyValue("system:max-memory-request");
       if (value != (char *) NULL)
         {
@@ -1019,8 +1022,6 @@ MagickExport size_t GetMaxMemoryRequest(void)
           max_memory_request=StringToSizeType(value,100.0);
           value=DestroyString(value);
         }
-      else
-        max_memory_request=(size_t) MagickULLConstant(~0);
     }
   return(max_memory_request);
 }
@@ -1413,8 +1414,10 @@ MagickExport void *ResizeQuantumMemory(void *memory,const size_t count,
   if (HeapOverflowSanityCheckGetSize(count,quantum,&size) != MagickFalse)
     {
       memory=RelinquishMagickMemory(memory);
-      return((void *) NULL);
+      return(NULL);
     }
+  if (size > GetMaxMemoryRequest())
+    return(NULL);
   return(ResizeMagickMemory(memory,size));
 }
